<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Check, ChevronDown, ChevronRight, Copy, Lock, Pencil, ReceiptText, Trash2 } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { TransactionRange } from '@/domain/services/date-range'
import { dayGroupTitle, groupTitleOf, groupTitleSubtitleOf, localDateKey } from '@/domain/services/date-range'
import { formatCents } from '@/domain/services/money'
import { groupTransactions, summarize } from '@/domain/services/statistics'
import { useAppStore } from '@/stores/app-store'
import CategoryIcon from '@/components/CategoryIcon.vue'
import { colorOf, softOf } from '@/domain/services/category-color'
import AppDialog from '@/components/AppDialog.vue'
import ConfirmGraphic from '@/components/ConfirmGraphic.vue'

const store = useAppStore()
const route = useRoute()
const router = useRouter()
const allowed: TransactionRange[] = ['day', 'week', 'month', 'year']
const initial = allowed.includes(route.query.range as TransactionRange) ? route.query.range as TransactionRange : 'month'
const range = ref<TransactionRange>(initial)
const expanded = ref(new Set<string>())
const initializedRange = ref<TransactionRange>()
const activationOpen = ref(false)
const rangeMenuOpen = ref(false)
const rangeMenu = ref<HTMLElement>()
const openSwipeId = ref<string | null>(null)
const swipeOffset = ref(0)
const pendingDeleteId = ref<string>()
const pendingDeleteLabel = ref('')
const deleting = ref(false)
const didSwipe = ref(false)
const labels: Record<TransactionRange, string> = { day: '天', week: '周', month: '月', year: '年' }
const SWIPE_REVEAL_PX = 228
const SWIPE_THRESHOLD_PX = 10
const SWIPE_CLOSE_THRESHOLD_PX = 10

type SwipeGesture = {
  id: string
  pointerId: number
  startX: number
  startY: number
  startOffset: number
  dragging: boolean
  cancelled: boolean
}
const swipeGesture = ref<SwipeGesture>()

const categories = computed(() => new Map(store.categories.map((category) => [category.id, category])))
const groups = computed(() => [...groupTransactions(store.transactions, range.value)].map(([key, items]) => ({ key, items, summary: summarize(items) })))
const titleItems = computed(() => groups.value.map((group) => ({
  ...group,
  title: groupTitleOf(range.value, group.key),
  subtitle: groupTitleSubtitleOf(range.value, group.key),
})))

watch(groups, (value) => {
  if (value.length && initializedRange.value !== range.value) {
    expanded.value = new Set([value[0].key])
    initializedRange.value = range.value
  }
}, { immediate: true })
watch(range, (value) => {
  expanded.value = new Set()
  initializedRange.value = undefined
  rangeMenuOpen.value = false
  closeSwipe()
  router.replace({ query: { ...route.query, range: value } })
}, { flush: 'sync' })
watch(() => route.query.range, (value) => {
  if (allowed.includes(value as TransactionRange) && value !== range.value) range.value = value as TransactionRange
})

function closeRangeMenu(event: PointerEvent): void {
  if (!rangeMenu.value?.contains(event.target as Node)) rangeMenuOpen.value = false
}

function closeSwipe(): void {
  openSwipeId.value = null
  swipeOffset.value = 0
  swipeGesture.value = undefined
}

function closeSwipeOnOutside(event: PointerEvent): void {
  const target = event.target as Element | null
  if (!target?.closest('.transaction-swipe-row')) closeSwipe()
}

function closeSwipeOnEscape(event: KeyboardEvent): void {
  if (event.key === 'Escape') closeSwipe()
}

function onSwipePointerDown(id: string, event: PointerEvent): void {
  if (event.pointerType === 'mouse' && event.button !== 0) return
  const target = event.target as Element | null
  if (target?.closest('.transaction-actions')) return
  const startOffset = openSwipeId.value === id ? swipeOffset.value : 0
  if (openSwipeId.value && openSwipeId.value !== id) closeSwipe()
  swipeGesture.value = {
    id,
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    startOffset,
    dragging: false,
    cancelled: false,
  }
  didSwipe.value = false
}

function onSwipePointerMove(id: string, event: PointerEvent): void {
  if (!swipeGesture.value || swipeGesture.value.id !== id || swipeGesture.value.pointerId !== event.pointerId || swipeGesture.value.cancelled) return
  const deltaX = event.clientX - swipeGesture.value.startX
  const deltaY = event.clientY - swipeGesture.value.startY
  if (!swipeGesture.value.dragging) {
    if (Math.abs(deltaX) < 6 && Math.abs(deltaY) < 6) return
    if (Math.abs(deltaY) > Math.abs(deltaX)) {
      swipeGesture.value.cancelled = true
      return
    }
    swipeGesture.value.dragging = true
    const target = event.currentTarget as HTMLElement | null
    if (target && typeof target.setPointerCapture === 'function') target.setPointerCapture(event.pointerId)
  }
  event.preventDefault()
  const nextOffset = Math.max(-SWIPE_REVEAL_PX, Math.min(0, swipeGesture.value.startOffset + deltaX))
  openSwipeId.value = id
  swipeOffset.value = nextOffset
}

function onSwipePointerUp(id: string, event: PointerEvent): void {
  if (!swipeGesture.value || swipeGesture.value.id !== id || swipeGesture.value.pointerId !== event.pointerId) return
  const current = swipeGesture.value
  swipeGesture.value = undefined
  if (current.cancelled || !current.dragging) return
  event.preventDefault()
  const target = event.currentTarget as HTMLElement | null
  if (target && typeof target.releasePointerCapture === 'function' && target.hasPointerCapture?.(event.pointerId)) target.releasePointerCapture(event.pointerId)
  didSwipe.value = true
  const deltaX = event.clientX - current.startX
  // 已展开时按“向右拖动距离”关闭，不要求把整块内容拖回到边缘，轻推即可收起。
  const shouldClose = current.startOffset < 0 && deltaX >= SWIPE_CLOSE_THRESHOLD_PX
  const shouldOpen = !shouldClose && (current.startOffset < 0 || deltaX <= -SWIPE_THRESHOLD_PX)
  openSwipeId.value = shouldOpen ? id : null
  swipeOffset.value = shouldOpen ? -SWIPE_REVEAL_PX : 0
}

function onSwipePointerCancel(id: string, event: PointerEvent): void {
  if (!swipeGesture.value || swipeGesture.value.id !== id || swipeGesture.value.pointerId !== event.pointerId) return
  swipeGesture.value = undefined
  swipeOffset.value = openSwipeId.value === id ? -SWIPE_REVEAL_PX : 0
}

function onTransactionClick(id: string): void {
  if (didSwipe.value) {
    didSwipe.value = false
    return
  }
  if (openSwipeId.value === id) {
    closeSwipe()
    return
  }
  edit(id)
}

function actionLabel(item: typeof store.transactions[number]): string {
  return categories.value.get(item.categoryId)?.name ?? '未分类'
}

function copyTransaction(id: string): void {
  if (!store.canWrite) { closeSwipe(); activationOpen.value = true; return }
  closeSwipe()
  void router.push({ name: 'record-new', query: { copyFrom: id } })
}

function editTransaction(id: string): void {
  closeSwipe()
  edit(id)
}

function requestDelete(item: typeof store.transactions[number]): void {
  if (!store.canWrite) { closeSwipe(); activationOpen.value = true; return }
  pendingDeleteId.value = item.id
  pendingDeleteLabel.value = actionLabel(item)
}

function cancelDelete(): void {
  if (deleting.value) return
  pendingDeleteId.value = undefined
  pendingDeleteLabel.value = ''
}

async function confirmDelete(): Promise<void> {
  if (!pendingDeleteId.value || deleting.value || !store.canWrite) return
  deleting.value = true
  try {
    await store.repository.deleteTransaction(pendingDeleteId.value)
    await store.refresh()
    store.notify('流水已删除', 'success')
    closeSwipe()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '删除失败，请重试', 'error')
  } finally {
    deleting.value = false
    pendingDeleteId.value = undefined
    pendingDeleteLabel.value = ''
  }
}

onMounted(() => {
  store.initialize()
  document.addEventListener('pointerdown', closeRangeMenu)
  document.addEventListener('pointerdown', closeSwipeOnOutside)
  document.addEventListener('keydown', closeSwipeOnEscape)
})
onBeforeUnmount(() => {
  document.removeEventListener('pointerdown', closeRangeMenu)
  document.removeEventListener('pointerdown', closeSwipeOnOutside)
  document.removeEventListener('keydown', closeSwipeOnEscape)
  closeSwipe()
})

function toggle(key: string): void {
  const next = new Set(expanded.value)
  next.has(key) ? next.delete(key) : next.add(key)
  expanded.value = next
}

function dayBuckets(items: typeof store.transactions): [string, typeof store.transactions][] {
  const buckets = new Map<string, typeof store.transactions>()
  for (const item of items) {
    const key = localDateKey(item.bookedAt)
    buckets.set(key, [...(buckets.get(key) ?? []), item])
  }
  return [...buckets]
}

function iconStyle(category: ReturnType<typeof categories.value.get> | undefined): { background: string; color: string } {
  const color = category ? colorOf(category, store.categories) : '#1677ff'
  return { background: softOf(color), color }
}

function edit(id: string): void {
  if (!store.canWrite) { activationOpen.value = true; return }
  router.push(`/record/${id}`)
}
</script>

<template>
  <Teleport to="#topbar-actions">
    <div ref="rangeMenu" class="range-menu">
      <button class="range-trigger" type="button" aria-haspopup="menu" :aria-expanded="rangeMenuOpen" @click="rangeMenuOpen = !rangeMenuOpen">
        {{ labels[range] }}<ChevronDown :size="18" aria-hidden="true" />
      </button>
      <div v-if="rangeMenuOpen" class="range-options" role="menu" aria-label="流水分组方式">
        <button v-for="item in allowed" :key="item" type="button" role="menuitemradio" :aria-checked="range === item" @click="range = item">
          <Check :size="18" :class="{ hidden: range !== item }" aria-hidden="true" />
          <span :class="{ active: range === item }">{{ labels[item] }}</span>
        </button>
      </div>
    </div>
  </Teleport>

  <main class="page transactions-page">
    <section v-if="groups.length === 0" class="empty card">
      <ReceiptText :size="44" aria-hidden="true" />
      <h2>还没有流水</h2>
      <p>点击下方“记一笔”记录第一笔收支。</p>
      <RouterLink class="button primary" to="/record">记一笔</RouterLink>
    </section>

    <section v-for="group in titleItems" :key="group.key" class="transaction-group card">
      <button class="group-header" type="button" :aria-expanded="expanded.has(group.key)" @click="toggle(group.key)">
        <span class="group-title">
          <component :is="expanded.has(group.key) ? ChevronDown : ChevronRight" :size="20" />
          <span class="group-title-stack">
            <span class="group-title-primary">{{ group.title }}</span>
            <span v-if="group.subtitle" class="group-title-secondary">{{ group.subtitle }}</span>
          </span>
        </span>
        <span class="group-summary"><span class="income">收 {{ formatCents(group.summary.incomeCents) }}</span><span class="expense">支 {{ formatCents(group.summary.expenseCents) }}</span></span>
      </button>
      <div v-if="expanded.has(group.key)" class="group-content">
        <template v-for="[day, items] in dayBuckets(group.items)" :key="day">
          <div v-if="range !== 'day'" class="day-header"><span>{{ dayGroupTitle(range, day) }}</span><span>共 {{ items.length }} 笔</span></div>
          <div
            v-for="item in items"
            :key="item.id"
            class="transaction-swipe-row"
            :class="{ 'is-open': openSwipeId === item.id, 'is-dragging': swipeGesture?.id === item.id && swipeGesture.dragging }"
          >
            <div class="transaction-actions" :aria-label="`${actionLabel(item)}操作`">
              <button class="transaction-action copy" type="button" :aria-label="`复制 ${actionLabel(item)}`" @pointerdown.stop @click.stop="copyTransaction(item.id)">
                <Copy :size="18" aria-hidden="true" />
                <span>复制</span>
              </button>
              <button class="transaction-action edit" type="button" :aria-label="`编辑 ${actionLabel(item)}`" @pointerdown.stop @click.stop="editTransaction(item.id)">
                <Pencil :size="18" aria-hidden="true" />
                <span>编辑</span>
              </button>
              <button class="transaction-action delete" type="button" :aria-label="`删除 ${actionLabel(item)}`" @pointerdown.stop @click.stop="requestDelete(item)">
                <Trash2 :size="18" aria-hidden="true" />
                <span>删除</span>
              </button>
            </div>
            <button
              class="transaction-row transaction-content"
              type="button"
              :style="{ transform: `translate3d(${openSwipeId === item.id ? swipeOffset : 0}px, 0, 0)` }"
              @pointerdown="onSwipePointerDown(item.id, $event)"
              @pointermove="onSwipePointerMove(item.id, $event)"
              @pointerup="onSwipePointerUp(item.id, $event)"
              @pointercancel="onSwipePointerCancel(item.id, $event)"
              @click="onTransactionClick(item.id)"
            >
              <span class="transaction-icon" :style="iconStyle(categories.get(item.categoryId))"><CategoryIcon :name="categories.get(item.categoryId)?.icon" /></span>
              <span class="transaction-main"><strong>{{ actionLabel(item) }}</strong><small>{{ item.note || new Date(item.bookedAt).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }}</small></span>
              <strong class="money" :class="item.type">{{ item.type === 'income' ? '+' : '-' }}{{ formatCents(item.amountCents) }}</strong>
            </button>
          </div>
        </template>
      </div>
    </section>
  </main>

  <AppDialog :open="activationOpen" title="功能未解锁" position="center" @close="activationOpen = false">
    <ConfirmGraphic :icon="Lock" strong="激活授权码后即可记账" sub="可记账和编辑流水，浏览账目不受影响" />
    <template #actions>
      <button class="button secondary equal-action" type="button" @click="activationOpen = false">暂不</button>
      <button class="button primary equal-action" type="button" @click="router.push('/settings/license')">去激活</button>
    </template>
  </AppDialog>

  <AppDialog :open="Boolean(pendingDeleteId)" title="删除流水" position="center" @close="cancelDelete">
    <ConfirmGraphic :icon="Trash2" tone="danger" :strong="`确定删除「${pendingDeleteLabel}」？`" sub="删除后不可恢复，请确认操作。" />
    <template #actions>
      <button class="button secondary equal-action" type="button" :disabled="deleting" @click="cancelDelete">取消</button>
      <button class="button danger equal-action" type="button" :disabled="deleting" @click="confirmDelete">{{ deleting ? '删除中…' : '确认删除' }}</button>
    </template>
  </AppDialog>
</template>

